import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.bigbang.*;import idle.core.molecules.*;import idle.core.sky.*;import idle.core.achievements.*;import idle.core.save.*;import java.util.*;import java.nio.file.*;
public class ProbeCosmos{public static void main(String[]args)throws Exception{Game g=new Game(SaveCodec.read(Files.readString(Path.of(args[0]))).state(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,Achievements.DEFAULT,new Random(42));System.out.printf("bb=%d time=%.2f expl=%d challenges=%d density=%d overflow=%d dark=%s freeSpace=%s auto=%s\n",g.bigBangs(),g.state().timePlayed()/3600,g.state().explosions(),g.completedChallenges(),g.darkLevelOf("dark_density"),g.darkLevelOf("dark_overflow"),g.state().darkMatter(),g.freeSpace(),g.isAutoCreatingMolecules());System.out.printf("shopping=%s target=%s ready=%s matter=%s sorts=%s\n",g.shoppingList().kind(),g.shoppingList().target(),g.shoppingList().ready(),g.shoppingList().matter(),g.shoppingList().sorts());for(ShoppingList.Item i:g.shoppingList().items()){String id=i.molecule().id();System.out.printf("  missing %s %d/%d gather=%s %s reachable=%s hasElements=%s space=%s next=%s\n",id,i.owned(),i.needed(),i.gather(),i.molecule().kind(),g.isMoleculeWithinReach(id),g.hasElementsForMolecule(id),g.hasSpaceForMolecule(id),g.nextMoleculeCost(id));}Body b=g.nextBody();if(b!=null){System.out.printf("body=%s conditions=%d/%d\n",b.id(),g.bodyConditionsMet(b.id()),g.bodyConditions(b.id()));System.out.println("made="+b.assemblies()+"bodyreq="+b.bodies()+"molreq="+b.molecules()+"matter="+b.matter());}for(Molecule m:g.molecules()){if(m.hasState() && m.state()==Molecule.State.GAS && g.moleculeCount(m.id())>0)System.out.println("GAS: "+m.id()+" count="+g.moleculeCount(m.id())+" gathered="+g.hasSubstance(m.id()));}
for(Molecule m:g.molecules()){if(m.hasState()&&m.state()==Molecule.State.METAL)System.out.printf("METAL:%s count=%d gathered=%s affordable=%s reach=%s kind=%s\n",m.id(),g.moleculeCount(m.id()),g.hasSubstance(m.id()),g.canCreateMolecule(m.id()),g.isMoleculeWithinReach(m.id()),m.kind());}
for(Molecule m:g.molecules()){if(g.canCreateMolecule(m.id())){System.out.println("CREATABLE: "+m.id()+" count="+g.moleculeCount(m.id())+" kind="+m.kind());}}}}
